//! Binary files attached to cells. A cell value holds file refs ({id, name, mime_type, size_bytes});
//! the bytes live here. Ids are generated by the client, so uploads are idempotent and retryable.

use axum::{
    body::Bytes,
    extract::{Path, State},
    http::{header, HeaderMap, HeaderValue, StatusCode},
    response::{IntoResponse, Response},
    Json,
};
use percent_encoding::{percent_decode_str, utf8_percent_encode, NON_ALPHANUMERIC};
use serde::Serialize;

use crate::data_row::AppState;

/// Largest accepted upload (audio clips, covers, scripts).
pub const MAX_FILE_BYTES: usize = 200 * 1024 * 1024;

#[derive(Debug, Clone)]
pub struct StoredFile {
    pub id: String,
    pub name: String,
    pub mime_type: String,
    pub content: Vec<u8>,
}

/// What a cell stores for each file.
#[derive(Debug, Serialize)]
pub struct FileRef {
    pub id: String,
    pub name: String,
    pub mime_type: String,
    pub size_bytes: usize,
}

fn validate_file_id(id: &str) -> Result<(), (StatusCode, String)> {
    let valid = !id.is_empty() && id.len() <= 64 && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
    if valid { Ok(()) } else { Err((StatusCode::BAD_REQUEST, format!("invalid file id '{id}'"))) }
}

fn header_str<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {
    headers.get(name).and_then(|value| value.to_str().ok())
}

/// `PUT /files/:id` — raw body; `Content-Type` = mime type, `X-File-Name` = percent-encoded name.
pub async fn put(
    State(state): State<AppState>,
    Path(id): Path<String>,
    headers: HeaderMap,
    body: Bytes,
) -> Result<(StatusCode, Json<FileRef>), (StatusCode, String)> {
    validate_file_id(&id)?;
    let name = header_str(&headers, "x-file-name")
        .map(|raw| percent_decode_str(raw).decode_utf8_lossy().into_owned())
        .filter(|name| !name.trim().is_empty())
        .unwrap_or_else(|| id.clone());
    let mime_type = header_str(&headers, header::CONTENT_TYPE.as_str())
        .unwrap_or("application/octet-stream")
        .to_string();
    let file = StoredFile { id: id.clone(), name, mime_type, content: body.to_vec() };
    tracing::info!(file_id = %id, name = %file.name, mime = %file.mime_type, bytes = file.content.len(), "file upload");
    state.store.put_file(&file).await.map_err(|e| crate::error::db_err("file", e))?;
    Ok((StatusCode::CREATED, Json(FileRef { id, name: file.name, mime_type: file.mime_type, size_bytes: file.content.len() })))
}

/// Parse a single `Range: bytes=…` header into an inclusive byte range within `len`.
fn parse_range(range: &str, len: usize) -> Option<(usize, usize)> {
    let spec = range.strip_prefix("bytes=")?.split(',').next()?.trim();
    let (start, end) = spec.split_once('-')?;
    let (start, end) = match (start.trim(), end.trim()) {
        ("", suffix) => {
            let suffix: usize = suffix.parse().ok()?;
            (len.checked_sub(suffix.min(len))?, len.checked_sub(1)?)
        }
        (start, "") => (start.parse().ok()?, len.checked_sub(1)?),
        (start, end) => (start.parse().ok()?, end.parse::<usize>().ok()?.min(len.checked_sub(1)?)),
    };
    (start <= end && end < len).then_some((start, end))
}

/// `GET /files/:id` — serves the bytes inline, honouring `Range` so audio/video can seek.
pub async fn get(
    State(state): State<AppState>,
    Path(id): Path<String>,
    headers: HeaderMap,
) -> Result<Response, (StatusCode, String)> {
    validate_file_id(&id)?;
    let file = state
        .store
        .get_file(&id)
        .await
        .map_err(|e| crate::error::db_err("file", e))?
        .ok_or((StatusCode::NOT_FOUND, format!("file '{id}' not found")))?;
    let len = file.content.len();
    let disposition = format!("inline; filename*=UTF-8''{}", utf8_percent_encode(&file.name, NON_ALPHANUMERIC));
    let mut response_headers = HeaderMap::new();
    let content_type = HeaderValue::from_str(&file.mime_type).unwrap_or(HeaderValue::from_static("application/octet-stream"));
    response_headers.insert(header::CONTENT_TYPE, content_type);
    response_headers.insert(header::ACCEPT_RANGES, HeaderValue::from_static("bytes"));
    // Content under an id never changes.
    response_headers.insert(header::CACHE_CONTROL, HeaderValue::from_static("private, max-age=31536000, immutable"));
    if let Ok(value) = HeaderValue::from_str(&disposition) {
        response_headers.insert(header::CONTENT_DISPOSITION, value);
    }

    match header_str(&headers, header::RANGE.as_str()) {
        Some(range) => match parse_range(range, len) {
            Some((start, end)) => {
                let content_range = format!("bytes {start}-{end}/{len}");
                response_headers.insert(header::CONTENT_RANGE, HeaderValue::from_str(&content_range).expect("ascii"));
                Ok((StatusCode::PARTIAL_CONTENT, response_headers, file.content[start..=end].to_vec()).into_response())
            }
            None => {
                response_headers.insert(header::CONTENT_RANGE, HeaderValue::from_str(&format!("bytes */{len}")).expect("ascii"));
                Ok((StatusCode::RANGE_NOT_SATISFIABLE, response_headers).into_response())
            }
        },
        None => Ok((StatusCode::OK, response_headers, file.content).into_response()),
    }
}

#[cfg(test)]
mod tests {
    use super::parse_range;

    #[test]
    fn parses_common_ranges() {
        assert_eq!(parse_range("bytes=0-99", 1000), Some((0, 99)));
        assert_eq!(parse_range("bytes=500-", 1000), Some((500, 999)));
        assert_eq!(parse_range("bytes=-100", 1000), Some((900, 999)));
        assert_eq!(parse_range("bytes=900-5000", 1000), Some((900, 999)));
    }

    #[test]
    fn rejects_unsatisfiable_ranges() {
        assert_eq!(parse_range("bytes=1000-", 1000), None);
        assert_eq!(parse_range("bytes=5-2", 1000), None);
        assert_eq!(parse_range("items=0-1", 1000), None);
        assert_eq!(parse_range("bytes=0-1", 0), None);
    }
}
